const st = $getWorkflowStaticData('global');
const now = DateTime.now().setZone('America/Mexico_City');
const msgs = [];
const recs = [];
// Hora a la que corre «Preparar posts» de cada marca (ajústala si la cambias allá).
const PREP = { 'marca-a': { h: 10, m: 7 }, 'marca-b': { h: 12, m: 7 } };
// 1) ¿n8n estuvo detenido? Corre cada hora; si pasaron más de 2.5 h desde la última vez, hubo caída.
if (st.ultima) {
  const antes = DateTime.fromISO(st.ultima).setZone('America/Mexico_City');
  const horas = now.diff(antes, 'hours').hours;
  if (horas > 2.5) msgs.push('🛑 n8n estuvo detenido unas ' + Math.round(horas) + ' h (del ' + antes.toFormat('dd/MM HH:mm') + ' al ' + now.toFormat('dd/MM HH:mm') + '). Los flujos programados de ese lapso no corrieron.');
}
st.ultima = now.toISO();
// 2) Posts
const hoy = now.toFormat('yyyy-MM-dd');
const manana = now.plus({ days: 1 }).toFormat('yyyy-MM-dd');
st.avisados = st.avisados || {};
for (const [k, v] of Object.entries(st.avisados)) if (now.diff(DateTime.fromISO(v), 'days').days > 10) delete st.avisados[k];
const enTxt = min => { min = Math.max(1, Math.round(min)); return min < 60 ? min + ' min' : Math.floor(min / 60) + ' h' + (min % 60 ? ' ' + (min % 60) + ' min' : ''); };
for (const r of $('Leer Calendario').all().map(i => i.json)) {
  const id = String(r.post_id || '').trim(); if (!id) continue;
  const estado = String(r.estado || '').trim();
  const fecha = String(r.fecha || '').trim(); if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha)) continue;
  const marca = String(r.marca || '').trim();
  const cuando = DateTime.fromFormat(fecha + ' ' + (String(r.hora || '00:00').trim() || '00:00'), 'yyyy-MM-dd HH:mm', { zone: 'America/Mexico_City' });
  if (!cuando.isValid || now.diff(cuando, 'days').days > 7) continue;
  // Nada se publica sin aprobación: si sigue sin aprobar, recuerda ~3 h antes y en la última hora.
  if (estado === 'por aprobar' || estado === 'cambios pedidos') {
    const faltan = cuando.diff(now, 'minutes').minutes;
    if (faltan > 0 && faltan <= 180) {
      const etapa = faltan <= 60 ? 'ultimo' : 'primero';
      const key = 'rec|' + id + '|' + String(r.version || '') + '|' + etapa;
      if (!st.avisados[key]) {
        st.avisados[key] = now.toISO();
        const dia = fecha === hoy ? 'hoy' : fecha === manana ? 'mañana' : cuando.toFormat('dd/MM');
        const que = estado === 'cambios pedidos' ? 'pediste cambios y la nueva versión todavía no está aprobada' : 'sigue sin aprobar';
        recs.push({ json: { tipo: 'recordatorio', reply: String(r.tg_msg || '').trim(),
          texto: (etapa === 'ultimo' ? '⏰ Última llamada: ' : '⏰ Recordatorio: ') + id + ' (' + marca + ') se publica ' + dia + ' a las ' + cuando.toFormat('HH:mm') + ' (en ' + enTxt(faltan) + ') y ' + que + '. Si no lo apruebas, no sale.' } });
      }
    }
  }
  const p = PREP[marca] || { h: 10, m: 7 };
  const prepHoy = now.set({ hour: p.h, minute: p.m, second: 0 }).plus({ minutes: 45 });
  let problema = '';
  if (estado === 'planeado' && (fecha < hoy || ((fecha === hoy || fecha === manana) && now > prepHoy))) problema = 'no se preparó: no te llegó a Telegram';
  else if (estado === 'error al preparar') problema = 'falló al prepararse';
  else if (estado === 'error al publicar') problema = 'falló al publicarse';
  else if (estado === 'aprobado' && !String(r.fb_url || '').trim() && now > cuando.plus({ minutes: 90 })) problema = 'está aprobado pero no se publicó';
  else if ((estado === 'por aprobar' || estado === 'cambios pedidos') && now > cuando) problema = 'sigue «' + estado + '» y ya pasó su hora';
  if (!problema) continue;
  const key = id + '|' + estado + '|' + problema;
  if (st.avisados[key]) continue;
  st.avisados[key] = now.toISO();
  msgs.push('• ' + id + ' (' + marca + ', ' + cuando.toFormat('dd/MM HH:mm') + '): ' + problema + '.');
}
// 3) Artículos del blog por aprobar: una vez al día (corrida de las 9:40) recuerda los que esperan más de 20 h.
if (now.hour === 9) {
  const arts = [];
  for (const it of $('Leer seo_articulos').all()) {
    const a = it.json || {};
    if (!/aprobar/i.test(String(a.estado || ''))) continue;
    const t = DateTime.fromFormat(String(a.actualizado || ''), 'yyyy-MM-dd HH:mm', { zone: 'America/Mexico_City' });
    if (t.isValid && now.diff(t, 'hours').hours < 20) continue;
    const key = 'art|' + a.id + '|' + String(a.version || '') + '|' + hoy;
    if (st.avisados[key]) continue;
    st.avisados[key] = now.toISO();
    arts.push('• ' + a.marca + ': «' + String(a.titulo || a.keyword || a.tema || '').slice(0, 80) + '»');
  }
  if (arts.length) recs.push({ json: { tipo: 'recordatorio', reply: '', texto: '📝 Artículos del blog esperando tu aprobación (no se publican sin tu ✅):\n' + arts.join('\n') } });
}
const out = [];
if (msgs.length) out.push({ json: { tipo: 'alerta', texto: '👀 Vigilante\n' + msgs.join('\n') } });
return out.concat(recs);
